package com.library.controller;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.library.entity.*;
import com.library.dto.BorrowRequest;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:structured-location-acceptance;DB_CLOSE_DELAY=-1;MODE=MYSQL")
class StructuredLocationControllerTest extends BookCopyActionControllerTest {
    protected record Address(long shelf,long storey,long id) {}
    @Test void multipleTitlesShareCapacityOneAddressWithoutConvertingLegacyBindingOrRawText()throws Exception{
        Address a=address();Book first=book(2,2),second=book(1,1);BookCopy x=copy(first,"AVAILABLE","  原位置  "),y=copy(first,"AVAILABLE",null),z=copy(second,"AVAILABLE","");
        response(put("/bookshelves/locations/"+a.id()+"/assign/"+second.getId()),version(0),"librarian",200);var oldBook=snapshot("book",first.getId());var oldBinding=snapshot("book_location",a.id());ObjectNode move=request2("MOVE",x,y,z);for(JsonNode input:move.path("copies"))((ObjectNode)input).set("targetLocation",registered(a.id()));
        JsonNode receipt=confirm(move,preview2(move),"admin");assertEquals(2,receipt.path("schemaVersion").asInt());assertEquals(oldBook,snapshot("book",first.getId()));assertEquals(oldBinding,snapshot("book_location",a.id()));assertEquals(0,countFor("stock_flow","book_id=?",first.getId()));assertEquals("  原位置  ",copies.selectById(x.getId()).getLocation());
        JsonNode row=data(get("/location-addresses/"+a.id()),"librarian",200);assertTrue(row.path("address").path("selectable").asBoolean());assertEquals(3,row.path("linkedCopyCount").asInt());assertEquals(second.getId().longValue(),row.path("legacyBinding").path("bookId").asLong());assertTrue(row.path("legacyBinding").path("needsReview").asBoolean());
        for(BookCopy c:List.of(x,y,z)){JsonNode current=current(c);assertEquals("REGISTERED",current.path("placement").path("kind").asText());assertFalse(current.path("unassignedLocation").asBoolean());assertFalse(current.path("locationReferenceAnomaly").asBoolean());assertTrue(current.path("lastLocationActionId").asLong()>0);}
        assertEquals(3,data(get("/book-copies").param("registeredLocationId",Long.toString(a.id())),"admin",200).path("total").asInt());
        JsonNode legacy=data(get("/books/"+first.getId()+"/copies"),"admin",200);assertEquals(2,legacy.size());assertEquals("REGISTERED",legacy.get(0).path("placement").path("kind").asText());
        ObjectNode same=move(x,a.id());reason(post("/book-copy-actions/v2/previews"),same,"admin",409,"INVALID_TRANSITION");
    }
    @Test void allStateActionsKeepRegisteredPlacementUntilRestoreExplicitlyClearsIt()throws Exception{
        Address a=address();Book b=book(1,1);BookCopy c=copy(b,"AVAILABLE","保留原文");ObjectNode move=move(c,a.id());JsonNode moved=confirm(move,preview2(move),"admin");long source=moved.path("copies").get(0).path("eventId").asLong();
        for(String action:List.of("DISABLE","ENABLE","WRITE_OFF")){ObjectNode r=request2(action,c);JsonNode receipt=confirm(r,preview2(r),"admin");assertEquals("KEEP",receipt.path("copies").get(0).path("locationSourceBehavior").asText());assertEquals(source,copies.selectById(c.getId()).getLastLocationActionId());assertEquals(a.id(),copies.selectById(c.getId()).getRegisteredLocationId());assertEquals("保留原文",copies.selectById(c.getId()).getLocation());assertFalse(current(c).path("locationReferenceAnomaly").asBoolean());}
        assertEquals(1,data(get("/location-addresses/"+a.id()),"admin",200).path("linkedCopyCount").asInt());ObjectNode r=request2("RESTORE",c);restore(r,c,null);JsonNode restored=confirm(r,preview2(r),"admin");assertNull(copies.selectById(c.getId()).getRegisteredLocationId());assertNull(copies.selectById(c.getId()).getLocation());assertEquals("DISABLED",copies.selectById(c.getId()).getStatus());assertEquals(restored.path("copies").get(0).path("eventId").asLong(),copies.selectById(c.getId()).getLastLocationActionId());assertFalse(current(c).path("locationReferenceAnomaly").asBoolean());
        ObjectNode enable=request2("ENABLE",c);confirm(enable,preview2(enable),"admin");BorrowRequest br=new BorrowRequest();br.setBookId(b.getId());br.setCopyId(c.getId());br.setUserId(reader());long version=copies.selectById(c.getId()).getActionVersion();Long pointer=copies.selectById(c.getId()).getLastLocationActionId();BorrowRecord loan=borrows.borrow(br);borrows.returnBook(loan.getId());assertEquals(version+2,copies.selectById(c.getId()).getActionVersion());assertEquals(pointer,copies.selectById(c.getId()).getLastLocationActionId());
    }
    @Test void parentRenameAndRenameBackInvalidatePreviewAndPreserveHistoricalAddressSnapshot()throws Exception{
        Address a=address();Book b=book(2,2);BookCopy x=copy(b,"AVAILABLE",null),y=copy(b,"AVAILABLE",null);ObjectNode committed=move(x,a.id());JsonNode receipt=confirm(committed,preview2(committed),"admin");ObjectNode pending=move(y,a.id());JsonNode preview=preview2(pending);String old=receipt.path("copies").get(0).path("afterPlacement").path("placement").path("registeredLocation").path("bookshelfName").asText();
        ObjectNode edit=shelfEdit(a.shelf(),"改名");response(put("/bookshelves"),edit,"librarian",200);assertEquals("改名",current(x).path("placement").path("registeredLocation").path("bookshelfName").asText());response(put("/bookshelves"),shelfEdit(a.shelf(),old),"admin",200);reason(post(confirmPath(preview)),confirmation(pending,preview),"admin",409,"PREVIEW_STALE");
        assertEquals(receipt,confirm(committed,data(get("/book-copy-actions/"+receipt.path("requestId").asLong()),"admin",200),"admin"));JsonNode history=data(get("/book-copies/"+x.getId()+"/actions"),"admin",200).path("records").get(0);assertEquals(old,history.path("locationChange").path("afterPlacement").path("placement").path("registeredLocation").path("bookshelfName").asText());assertEquals(0,history.path("locationChange").path("afterPlacement").path("placement").path("registeredLocation").path("bookshelfVersion").asLong());
        JsonNode events=data(get("/location-structure-events").param("entityType","BOOKSHELF").param("entityId",Long.toString(a.shelf())),"librarian",200);assertEquals(3,events.path("total").asInt());assertEquals("UPDATE",events.path("records").get(0).path("operation").asText());assertEquals(1,events.path("pages").asInt());
    }
    @Test void v1PersistentShapeAndOriginalReceiptSurviveNewRegisteredPlacement()throws Exception{
        Address a=address();Book b=book(1,1);BookCopy c=copy(b,"AVAILABLE",null);ObjectNode old=request("MOVE",c);location(old,"TEXT","旧原文");JsonNode preview=preview(old,"admin");List<String> before=actionJson(preview);JsonNode receipt=confirm(old,preview,"admin");assertFalse(receipt.path("copies").get(0).has("afterPlacement"));assertFalse(receipt.path("copies").get(0).has("afterLocationActionId"));assertEquals(before.subList(0,2),actionJson(preview).subList(0,2));assertEquals(0,countFor("book_copy_action_location","event_id=?",receipt.path("copies").get(0).path("eventId").asLong()));assertFalse(current(c).path("locationReferenceAnomaly").asBoolean());List<String> committedJson=actionJson(preview);
        ObjectNode pending=request("DISABLE",c);JsonNode oldPending=preview(pending,"admin");ObjectNode move=move(c,a.id());confirm(move,preview2(move),"admin");assertEquals(receipt,confirm(old,preview,"admin"));assertEquals(committedJson,actionJson(preview));reason(post(confirmPath(oldPending)),confirmation(pending,oldPending),"admin",409,"PREVIEW_STALE");reason(post("/book-copy-actions/previews"),request("DISABLE",c),"admin",409,"LOCATION_CONTRACT_UPGRADE_REQUIRED");
        ObjectNode sameKey=request2("DISABLE",c).put("idempotencyKey",old.path("idempotencyKey").asText());reason(post("/book-copy-actions/v2/previews"),sameKey,"admin",409,"IDEMPOTENCY_KEY_REUSED");
        JsonNode history=data(get("/book-copies/"+c.getId()+"/actions"),"admin",200).path("records");assertEquals(2,history.get(0).path("schemaVersion").asInt());assertEquals(1,history.get(1).path("schemaVersion").asInt());assertTrue(history.get(1).get("locationChange").isNull());
    }
    @Test void anomalousPriorSourceAndBrokenParentCanBeExplicitlyMovedOutWithoutRewritingEvidence()throws Exception{
        Address a=address();Book b=book(2,2);BookCopy x=copy(b,"AVAILABLE","x"),y=copy(b,"AVAILABLE","y");ObjectNode r=move(x,a.id());JsonNode receipt=confirm(r,preview2(r),"admin");long event=receipt.path("copies").get(0).path("eventId").asLong();String original=jdbc.queryForObject("SELECT after_json FROM book_copy_action_location WHERE event_id=?",String.class,event);
        jdbc.update("UPDATE book_copy SET registered_location_id=?,last_location_action_id=? WHERE id=?",a.id(),event,y.getId());assertTrue(current(y).path("locationReferenceAnomaly").asBoolean());ObjectNode out=request2("MOVE",y);location(out,"TEXT","人工明确新位");JsonNode p=preview2(out);assertTrue(p.path("warnings").toString().contains("LOCATION_REFERENCE_ANOMALY"));confirm(out,p,"admin");assertFalse(current(y).path("locationReferenceAnomaly").asBoolean());assertNull(copies.selectById(y.getId()).getRegisteredLocationId());assertEquals(original,jdbc.queryForObject("SELECT after_json FROM book_copy_action_location WHERE event_id=?",String.class,event));
        jdbc.update("UPDATE bookshelf SET deleted=1 WHERE id=?",a.shelf());assertEquals("REGISTERED",current(x).path("placement").path("kind").asText());assertTrue(current(x).path("locationReferenceAnomaly").asBoolean());ObjectNode clear=request2("MOVE",x);location(clear,"UNASSIGNED",null);confirm(clear,preview2(clear),"admin");assertFalse(current(x).path("locationReferenceAnomaly").asBoolean());assertEquals(1,jdbc.queryForObject("SELECT deleted FROM bookshelf WHERE id=?",Integer.class,a.shelf()));
        long latest=copies.selectById(y.getId()).getLastLocationActionId();jdbc.update("UPDATE book_copy_action_request SET state='PREVIEWED',committed_at=NULL,receipt_json=NULL WHERE id=(SELECT request_id FROM book_copy_action WHERE id=?)",latest);assertTrue(current(y).path("locationReferenceAnomaly").asBoolean());
    }
    @Test void strictV2BranchesAndMaintenanceInputsRejectUnknownNullCoercionAndMissingVersion()throws Exception{
        Address a=address();Book b=book(1,1);BookCopy c=copy(b,"AVAILABLE",null);List<ObjectNode> invalid=new ArrayList<>();invalid.add(move(c,a.id()).put("schemaVersion","2"));ObjectNode extra=move(c,a.id());((ObjectNode)extra.path("copies").get(0).path("targetLocation")).putNull("text");invalid.add(extra);ObjectNode bool=move(c,a.id());((ObjectNode)bool.path("copies").get(0)).put("expectedVersion",true);invalid.add(bool);ObjectNode nulls=request2("DISABLE",c);((ObjectNode)nulls.path("copies").get(0)).putNull("targetLocation");invalid.add(nulls);for(ObjectNode input:invalid)reason(post("/book-copy-actions/v2/previews"),input,"admin",400,"INVALID_INPUT");
        ObjectNode edit=shelfEdit(a.shelf(),"名称");edit.remove("expectedVersion");reason(put("/bookshelves"),edit,"admin",400,"INVALID_INPUT");edit=shelfEdit(a.shelf(),"名称");edit.put("expectedVersion","0");reason(put("/bookshelves"),edit,"admin",400,"INVALID_INPUT");ObjectNode body=version(0).put("deleted",1);reason(delete("/bookshelves/locations/"+a.id()),body,"admin",400,"INVALID_INPUT");response(delete("/bookshelves/locations/"+a.id()),version(0),"librarian",403);data(get("/location-addresses"),"reader",403);data(get("/location-structure-events").param("entityType","LOCATION").param("entityId",Long.toString(a.id())),"reader",403);
    }
    @Test void clearWritesNullPreservesDisabledAndCopiesAndMixedPutCannotReplaceLegacyBinding()throws Exception{
        Address a=address();Book b=book(1,1),other=book(1,1);BookCopy c=copy(b,"AVAILABLE",null);ObjectNode move=move(c,a.id());confirm(move,preview2(move),"admin");response(put("/bookshelves/locations/"+a.id()+"/assign/"+b.getId()),version(0),"admin",200);var copyBefore=snapshot("book_copy",c.getId());ObjectNode edit=locationEdit(a,"OCCUPIED").put("bookId",other.getId());reason(put("/bookshelves/locations"),edit,"admin",409,"LOCATION_IN_USE");
        response(put("/bookshelves/locations"),locationEdit(a,"DISABLED"),"admin",200);response(put("/bookshelves/locations/"+a.id()+"/clear"),version(2),"admin",200);assertNull(jdbc.queryForObject("SELECT book_id FROM book_location WHERE id=?",Long.class,a.id()));assertEquals("DISABLED",jdbc.queryForObject("SELECT status FROM book_location WHERE id=?",String.class,a.id()));assertEquals(copyBefore,snapshot("book_copy",c.getId()));reason(put("/bookshelves/locations/"+a.id()+"/clear"),version(2),"admin",409,"LOCATION_STALE");reason(delete("/bookshelves/locations/"+a.id()),version(3),"admin",409,"LOCATION_IN_USE");
        jdbc.update("UPDATE book_location SET status='EMPTY',book_id=? WHERE id=?",b.getId(),a.id());response(put("/bookshelves/locations/"+a.id()+"/clear"),version(3),"admin",200);assertNull(jdbc.queryForObject("SELECT book_id FROM book_location WHERE id=?",Long.class,a.id()));jdbc.update("UPDATE book_location SET status='原未知',book_id=? WHERE id=?",b.getId(),a.id());reason(put("/bookshelves/locations/"+a.id()+"/clear"),version(4),"admin",409,"LOCATION_UNAVAILABLE");assertEquals(b.getId(),jdbc.queryForObject("SELECT book_id FROM book_location WHERE id=?",Long.class,a.id()));
    }
    @Test void historicalSupplementAndProtectedSoftDeletedDescendantsBlockDeletion()throws Exception{
        Address a=address();Book b=book(1,1);BookCopy c=copy(b,"AVAILABLE",null);ObjectNode move=move(c,a.id());confirm(move,preview2(move),"admin");ObjectNode out=request2("MOVE",c);location(out,"TEXT","迁出");confirm(out,preview2(out),"admin");reason(delete("/bookshelves/locations/"+a.id()),version(0),"admin",409,"LOCATION_IN_USE");jdbc.update("UPDATE book_location SET deleted=1 WHERE id=?",a.id());reason(delete("/bookshelves/storeys/"+a.storey()),version(0),"admin",409,"LOCATION_IN_USE");jdbc.update("UPDATE bookshelf_storey SET deleted=1 WHERE id=?",a.storey());reason(delete("/bookshelves/"+a.shelf()),version(0),"admin",409,"LOCATION_IN_USE");
    }
    @Test void effectiveLocationFiltersUseJavaTrimSemanticsAndNeverSearchPreservedText()throws Exception{
        Address a=address();Book b=book(40,40);int unassigned=0;for(int cp=0;cp<=32;cp++){copy(b,"AVAILABLE",Character.toString(cp));unassigned++;}copy(b,"AVAILABLE",null);copy(b,"AVAILABLE","");unassigned+=2;BookCopy registered=copy(b,"AVAILABLE","保留文本");ObjectNode move=move(registered,a.id());confirm(move,preview2(move),"admin");copy(b,"AVAILABLE","\u00a0");copy(b,"AVAILABLE","文字");assertEquals(unassigned,data(get("/book-copies").param("bookId",b.getId().toString()).param("unassignedLocation","true"),"admin",200).path("total").asInt());assertEquals(2,data(get("/book-copies").param("bookId",b.getId().toString()).param("locationKind","TEXT"),"admin",200).path("total").asInt());assertEquals(0,data(get("/book-copies").param("bookId",b.getId().toString()).param("location","保留文本"),"admin",200).path("total").asInt());data(get("/book-copies").param("locationKind","TEXT").param("registeredLocationId",Long.toString(a.id())),"admin",400);
    }
    protected Address address()throws Exception{String code="A"+unique();ObjectNode shelf=json.createObjectNode().put("name","合成地址").put("code",code).putNull("deptId").putNull("location").put("capacity",1).put("status",1).put("reason","合成新建");long sid=response(post("/bookshelves"),shelf,"admin",200).path("data").path("id").asLong();ObjectNode storey=json.createObjectNode().put("bookshelfId",sid).put("name","合成层").put("levelNum",1).put("capacity",1).put("status",1).put("reason","合成新建");long tid=response(post("/bookshelves/storeys"),storey,"admin",200).path("data").path("id").asLong();long lid=response(post("/bookshelves/locations"),json.createObjectNode().put("storeyId",tid).put("code",code).put("status","EMPTY").put("reason","合成新建"),"admin",200).path("data").path("id").asLong();return new Address(sid,tid,lid);}
    protected ObjectNode registered(long id)throws Exception{JsonNode a=data(get("/location-addresses/"+id),"admin",200).path("address");ObjectNode t=json.createObjectNode().put("kind","REGISTERED").put("locationId",id);t.set("expectedAddressVersion",json.createObjectNode().put("location",a.path("locationVersion").asLong()).put("storey",a.path("storeyVersion").asLong()).put("bookshelf",a.path("bookshelfVersion").asLong()));return t;}
    protected ObjectNode request2(String action,BookCopy...copies){return request(action,copies).put("schemaVersion",2);}
    protected ObjectNode move(BookCopy c,long id)throws Exception{ObjectNode r=request2("MOVE",c);((ObjectNode)r.path("copies").get(0)).set("targetLocation",registered(id));return r;}
    protected JsonNode preview2(ObjectNode r)throws Exception{return response(post("/book-copy-actions/v2/previews"),r,"admin",200).path("data");}
    protected JsonNode current(BookCopy c)throws Exception{return data(get("/book-copies/"+c.getId()+"/action-context"),"admin",200).path("copy");}
    protected ObjectNode version(long value){return json.createObjectNode().put("expectedVersion",value).put("reason","合成现场依据");}
    protected ObjectNode shelfEdit(long id,String name){var row=jdbc.queryForMap("SELECT * FROM bookshelf WHERE id=?",id);return json.createObjectNode().put("id",id).put("expectedVersion",((Number)row.get("layout_version")).longValue()).put("name",name).put("code",(String)row.get("code")).putNull("deptId").putNull("location").put("capacity",1).put("status",((Number)row.get("status")).intValue()).put("reason","合成明确改名");}
    protected ObjectNode locationEdit(Address a,String status){long version=jdbc.queryForObject("SELECT layout_version FROM book_location WHERE id=?",Long.class,a.id());return json.createObjectNode().put("id",a.id()).put("expectedVersion",version).put("storeyId",a.storey()).put("code",jdbc.queryForObject("SELECT code FROM book_location WHERE id=?",String.class,a.id())).put("status",status).put("reason","合成明确编辑");}
    protected List<String> actionJson(JsonNode p){return jdbc.queryForObject("SELECT request_json,preview_json,receipt_json FROM book_copy_action_request WHERE id=?",(rs,n)->Arrays.asList(rs.getString(1),rs.getString(2),rs.getString(3)),p.path("requestId").asLong());}
    protected long countFor(String table,String where,Object...args){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE "+where,Long.class,args);}
}
